let s=fresh(),sandbox=null,battle=null,page='home',tab='overview',powerSort='default',difficulty='NORMAL',selectedFloor=1,saveError='',saveBlocked=false,toastTimer,cinemaTimer,alignmentRevealTimer,combatAnimating=false,combatRecovering=false,combatReleaseTimer,sound=false,audio=null,lastSummon=[],summonSession=null;
try{const loaded=load();if(loaded.error){saveError='既存セーブを読み込めません：'+loaded.error;saveBlocked=true;}else {s=loaded.state;battle=restoreMarkBattle(s.markBattle,validateSave);}}catch(e){saveError='保存領域を利用できません。JSONバックアップをご利用ください。';}
