function uiIcon(id,size=24){const shapes={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-8H9v8H4a1 1 0 0 1-1-1Z"/>',power:'<path d="m13 2-9 12h7l-1 8 10-13h-7Z"/>',star:'<path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5Z"/><path d="m20 2 1 3 3 1"/>',swords:'<path d="m4 3 7 5 10 11-2 2L8 11 3 4ZM3 18l3 3M2 22l5-5M20 3l-5 4-3 4m-1 3-6 7m13-18 3 3M17 17l5 5"/>',shield:'<path d="m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6Z"/>',crown:'<path d="m3 6 4 4 5-7 5 7 4-4-2 13H5ZM5 22h14"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',search:'<circle cx="10.5" cy="10.5" r="7"/><path d="m16 16 5 5"/>',skull:'<path d="M8 18H5v-4a9 9 0 1 1 14 0v4h-3v4H8Z"/><circle cx="8" cy="10" r="1"/><circle cx="16" cy="10" r="1"/><path d="m10 15 2-2 2 2M12 18v4"/>',gem:'<path d="m12 2 9 10-9 10-9-10Z"/><path d="m12 6 5 6-5 6-5-6Z"/>',flask:'<path d="M8 2h8M10 2v7l-6 10a2 2 0 0 0 2 3h12a2 2 0 0 0 2-3L14 9V2M7 15h10"/>',gear:'<path d="m9 3 1-2h4l1 2 3 2 2 1v4l-2 1v3l2 1v4l-2 1-3 2-1 2h-4l-1-2-3-2-2-1v-4l2-1v-3l-2-1V6l2-1Z"/><circle cx="12" cy="12" r="3"/>',book:'<path d="M12 5C8 2 4 2 2 3v17c3-1 6-1 10 1 4-2 7-2 10-1V3c-2-1-6-1-10 2Z"/><path d="M12 5v16"/>',arrow:'<path d="M6 18 18 6M6 6h12v12"/>'};return `<svg class="ui-icon" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${shapes[id]||shapes.gem}</svg>`;}
function characterSummary(a,p){return `<div class="row between" style="margin:0"><h3>いれーな</h3><span class="tag">Lv. ${a.level}</span></div><div class="small">${AWAKENINGS[a.awakening]}</div>${statsHTML(p)}<div class="row between"><span class="tag">EQUIPPED AUTHORITY</span>${button('装備変更','openupgrade','powers','ghost small')}</div><div class="equips">${[0,1].map(i=>`<div class="equip"><div class="emblem">${POWERS.find(x=>x.id===a.equipped[i])?.icon||'◇'}</div><div><strong>${a.equipped[i]?name(a.equipped[i]):'未装備'}</strong><small>${a.equipped[i]?'Lv. '+(a.powers[a.equipped[i]]||a.resonance[a.equipped[i]]):'EMPTY SLOT'}</small></div></div>`).join('')}</div><p class="footnote">徽章：${a.badge?{A:'火力',B:'技巧',C:'均衡'}[a.badge]+' '+['','I','II','III'][badgeRank(a,a.badge)]:'未装備'}　刻印 ${a.markEquip.length}/3<br>権能欠片 ${n(Object.values(a.fragments).reduce((x,y)=>x+y,0))} / 共鳴片 ${n(a.resShards)}</p>`;}
function statsHTML(p){return `<div class="statgrid">${[['hp','生命力'],['atk','攻撃力'],['def','防御力'],['spd','速度']].map(([k,v])=>`<div class="stat"><small>${v}</small><strong title="${n(p[k])}">${compact(p[k])}</strong></div>`).join('')}</div>`;}
function heading(title,sub,kicker){return `<div class="heading"><div><div class="tag">${kicker}</div><h1>${title}</h1><p>${sub}</p></div><span class="pill"><i class="pip"></i>${sandbox?'TEST REALM':'THE FALLEN STAR'}</span></div>`;}
function titleScreen(){return `<section class="title-screen"><img class="title-art" src="${MEDIA.keyArt}" alt="ユーザー提供キービジュアル"><div class="title-copy"><div class="tag">THE FALLEN STAR</div><h1>いれーな</h1><div class="reborn">REBORN</div><p>神威と堕天、その境界に立つ者。<br>これは、失われた力を取り戻す物語。</p>${button(s.started?'旅を続ける':'再誕の物語を始める','begin','','primary')}<div class="row" style="justify-content:center">${button('JSONから復元','import','','ghost')}</div><small>ブラウザに自動保存 / JSONバックアップ対応<br>いれーな REBORN · 失われた力を取り戻す物語</small>${saveError?`<p class="saved-error">${esc(saveError)}</p>`:''}</div></section>`;}
function render(){syncCombatBusy();const campaignScreen=page==='campaign'||page==='battle'&&battle?.campaign;const a=campaignScreen?campaign.build:current();if(!a.started){$('#app').innerHTML=titleScreen();return;}
 const navIcons={home:'home',upgrade:'power',battle:'swords',lab:'flask',dev:'gear'};
 const mobileNav=[['home','home','ホーム','nav','home'],['upgrade','power','強化','nav','upgrade'],['summon','star','ガチャ','openupgrade','summon'],['battle','swords','戦闘','nav','battle'],['raid','skull','レイド','nav','raid']];
 $('#app').innerHTML=`<aside class="sidebar"><div class="logo"><div class="crest">${uiIcon('crown',36)}</div><strong>いれーな</strong><small>R E B O R N</small></div><div class="tag" style="margin:0 12px 16px">SANCTUARY</div>${navs.map(([id,icon,title])=>`<button class="navbtn ${page===id?'active':''}" data-action="nav" data-id="${id}"><span>${uiIcon(navIcons[id],22)}</span><span>${title}</span></button>`).join('')}<div class="sidefoot"><div class="tag">THE FALLEN STAR</div><p>失われた力は、<br>まだこの翼の中に。</p>${button('資料・操作説明','about','','ghost small')}</div></aside><div class="shell ${page==='home'?'home-shell':page==='upgrade'?'upgrade-shell':page==='battle'&&battle?.character==='irena'?'standard-shell':''}">${campaignScreen?'<div class="test-banner">20階層【試作】・本編非反映・再読込でリセット</div>':''}${sandbox?`<div class="test-banner">試験用セーブで操作中 ${button('本編へ戻る','exitdev')}</div>`:''}${page==='home'?homeHeader(a):`<header class="topbar"><div class="arena-brand"><span class="brand-icon">${uiIcon('swords',26)}</span><div><strong>${page==='battle'&&battle?.character==='irena'?'いれーな REBORN':'バトルアリーナデュエル'}</strong><small>TACTICAL 1 VS 1 · TURN-BASED</small></div></div><div class="challenge-level"><i class="pip"></i>挑戦 Lv. <b>${a.floor}</b></div><div class="resources"><span class="resource gold">✦<b title="${n(a.p)}">${compact(a.p)}</b><small>P</small></span><span class="resource">◇<b title="${n(a.resShards)}">${compact(a.resShards)}</b><small>共鳴片</small></span><span class="resource">♜<b>${a.level}</b><small>Lv.</small></span></div><div class="header-tools"><div class="save-state ${saveError?'saved-error':''}">${campaignScreen?'試作・一時データ':saveError?'保存要確認':'● '+(sandbox?'試験データ':'AUTO SAVE')}</div>${button(sound?'音 ON':'音 OFF','sound','','soundtoggle ghost')}</div></header>`}<main class="content ${page==='home'?'home-page':page==='upgrade'?'upgrade-page':''} ${page==='battle'&&battle?'combat-page':''} ${page==='battle'&&battle?.character==='irena'?'standard-combat':''}">${saveError?`<div class="notice saved-error">${esc(saveError)} ${button('JSON書き出し','export')}</div>`:''}${page==='campaign'?campaignLobby(campaign,button):page==='home'?home(a):page==='upgrade'?upgrade(a):page==='battle'?battleView(a):page==='raid'?raidView(a):page==='archive'?archive(a):page==='lab'?lab(a):page==='awakening'?awakeningView(a):dev(a)}<footer class="utility-nav" aria-label="補助メニュー">${button(uiIcon('flask',16)+'実験場','nav','lab','ghost')}${button(uiIcon('gear',16)+'開発者','nav','dev','ghost')}${button(uiIcon('book',16)+'ガイド','about','','ghost')}</footer></main>${page==='upgrade'&&tab!=='overview'?`<div class="upgrade-fixed-back">${button('← 強化カテゴリに戻る','upgradeBack','','ghost')}</div>`:''}</div><nav class="mobile-nav ${page==='home'||page==='upgrade'?'home-nav':''}" aria-label="メインナビゲーション">${mobileNav.map(([id,icon,title,action,target])=>{const selected=id==='summon'?page==='upgrade'&&tab==='summon':id==='upgrade'?page==='upgrade'&&tab!=='summon':page===id;return `<button class="${selected?'active':''}" data-action="${action}" data-id="${target}" ${selected?'aria-current="page"':''}><span>${uiIcon(icon,25)}</span>${title}</button>`;}).join('')}</nav>`;
}

function homeHeader(a){return `<header class="topbar home-topbar"><div class="home-wordmark"><span>IRENA <b>✧</b> REBORN</span><small>いれーな リボーン</small></div><div class="home-profile"><img src="${HOME_ART.hero}" alt="" width="36" height="36"><div><small>Lv.${n(a.level)}</small><strong>いれーな</strong></div></div><div class="home-wallet" aria-label="所持素材"><span>${uiIcon('star',16)}<b data-home-value="p">${n(a.p)}</b><small>P</small></span><span>${uiIcon('gem',16)}<b data-home-value="shards">${n(a.resShards)}</b><small>共鳴片</small></span></div><div class="home-header-tools">${button(uiIcon('book',21),'nav','archive','ghost home-archive-shortcut').replace('<button ','<button aria-label="実績アーカイブ" ')}${button(uiIcon('gear',21),'about','','ghost home-guide-shortcut').replace('<button ','<button aria-label="仕様・操作ガイド" ')}</div><div class="home-save ${saveError?'saved-error':''}">${saveError?'保存要確認':sandbox?'試験データ':'● AUTO SAVE'}</div></header>`;}
function homeGoal(a){
 const gates=[[5,'権能「堕天」'],[10,'権能「堕天王」'],[20,'権能「断罪」'],[50,'共鳴・深淵レイド'],[100,'境界への扉']];
 const next=gates.find(([floor])=>!a.cleared.includes(floor));
 if(next)return {title:`カイザー Lv.${next[0]} を撃破する`,value:a.cleared.filter(x=>x<=next[0]).length,total:next[0],label:'攻略階層',reward:next[1]};
 if(!a.flags.warp)return {title:'境界を越え、ステラを解放する',value:0,total:1,label:'境界への扉',reward:'ステラモード'};
 if(!a.flags.ex)return {title:'EXカイザーを撃破する',value:0,total:1,label:'EXカイザー',reward:'神域連戦'};
 if(!a.flags.stellaClear)return {title:'ステラ最終決戦をクリアする',value:0,total:1,label:'ステラ最終決戦',reward:'専用いれーな'};
 if(!a.flags.finalClear)return {title:'いれーな最終決戦をクリアする',value:0,total:1,label:'いれーな最終決戦',reward:'最終決戦のクリア記録'};
 if(a.awakening<5)return {title:'失われた神格を取り戻す',value:a.awakening,total:5,label:'神格覚醒',reward:AWAKENINGS[a.awakening+1]};
 return {title:'すべての戦いの記憶を集める',value:a.achieved.length,total:36,label:'実績',reward:'天星覇権 Lv.5'};
}
