const UPGRADE_SECTIONS=[['powers','権能','深淵・黒翼・堕天・断罪など','権能の入手・強化・装備','violet'],['marks','刻印','刻印の装備・強化・管理','既存の刻印機能','red'],['resonance','権能共鳴','権能を組み合わせた共鳴権能','共鳴権能の作成・強化','gold'],['training','才能＆技','ステータス・才能・技の育成','既存の才能・技の育成','blue'],['summon','黒翼召喚','黒翼の召喚・育成・管理','既存の召喚機能','violet']];
function upgradeHero(a,detail=false){return `<header class="upgrade-hero"><img class="upgrade-hero-art" src="${UPGRADE_HERO}" alt=""><div class="upgrade-hero-copy"><span class="upgrade-crest" aria-hidden="true">✧</span><div><h1>${detail?'権能強化':'強化'}</h1><small>POWER UP</small><p>${detail?'強化する権能を選択してください':'強化したい項目を選択してください'}</p></div></div><div class="upgrade-wallet">権能ポイント <strong>✦ ${n(a.p)} P</strong></div></header>`;}
function upgrade(a){const section=UPGRADE_SECTIONS.find(x=>x[0]===tab);return `<div class="upgrade-ui">${upgradeHero(a,tab==='powers')}${tab==='overview'?`<section class="upgrade-category-list" aria-label="強化カテゴリ">${UPGRADE_SECTIONS.map(([id,title,desc,more,tone])=>`<button class="upgrade-category tone-${tone}" data-action="tab" data-id="${id}"><img src="${UPGRADE_ICONS[id]}" alt="" class="upgrade-category-icon"><span class="upgrade-category-copy"><strong>${title}</strong><span>${desc}</span><small>${more}</small></span><span class="upgrade-category-chevron" aria-hidden="true">›</span></button>`).join('')}</section><div class="upgrade-info">${uiIcon('book',26)}<span><strong>強化について</strong><small>項目を選択すると、既存の育成メニューに進みます。</small></span></div>`:`<section class="upgrade-subpage" aria-label="${section?.[1]||'育成'}">${tab==='powers'?powersView(a):`<h2 class="upgrade-subtitle">${section?.[1]||'育成'}</h2>${tab==='marks'?marksView(a):tab==='resonance'?resonanceView(a):tab==='training'?trainingView(a):summonView(a)}`}</section>`}</div>`;}
function powerStatus(a,p){
 const info=powerUpgradeInfo(a,p.id),selected=a.equipped.includes(p.id);
 const state=!info.lv?(p.id==='star'?'locked':'unowned'):info.max?'max':info.canUpgrade?'ready':'insufficient';
 const label={locked:'未解放',unowned:'未所持',max:'★ 最大レベル',ready:'↑ 強化可能',insufficient:'◇ 素材不足'}[state];
 return {...info,selected,state,label};
}
function powerDetails(a,p){
 const v=powerStatus(a,p),growth=lv=>Math.round((powerGrowth(lv)-1)*100),isStar=p.id==='star';
 const effect=lv=>`<p>${esc(p.effect)}</p>${!isStar?`<div class="detail-growth">育成補正：基礎HP・攻撃・防御・速度 <strong>＋${growth(lv)}%</strong></div>`:''}`;
 const next=v.max?'<p>★ 最大レベルに到達しています。</p>':!v.lv?`<p>${esc(p.source)}</p><small>${isStar?`実績 ${a.achieved.length} / ${ACHIEVEMENTS.length}`:'入手するとLv.1の固有効果が有効になります。'}</small><h3 class="unlock-effect-title">${isStar?'解放時の効果 · Lv.5':'入手時の効果 · Lv.1'}</h3>${effect(isStar?5:1)}`:effect(v.lv+1);
 return `<div class="upgrade-detail-modal"><header class="power-detail-heading"><img ${p.id!=='star'?`data-authority-art="${p.id}"`: ''} src="${UPGRADE_ART[p.id]}" alt=""><div><strong>${p.name}</strong><span>${v.lv?'Lv.'+v.lv+' / 5':'未解放・未所持'}</span><span class="power-state-badge badge-${v.state}">${v.label}</span>${v.selected?'<span class="power-equipped-badge">✓ 装備中</span>':''}</div></header><section class="upgrade-detail-section"><h3>現在の効果${v.lv?' · Lv.'+v.lv:''}</h3>${v.lv?effect(v.lv):'<p>未所持のため、まだ効果は発動しません。</p>'}</section><section class="upgrade-detail-section next-effect"><h3>${v.max?'強化完了':v.lv?'次レベルの効果 · Lv.'+(v.lv+1):'解放・入手条件'}</h3>${next}</section><dl class="power-detail-materials"><div><dt>強化に必要な欠片</dt><dd>${v.max?'— 最大レベル':!v.lv?'— 入手後に強化':n(v.cost)+' 個'}</dd></div><div><dt>所持欠片</dt><dd>${isStar?'— 実績報酬':n(v.have)+' 個'}</dd></div>${v.lv&&!v.max?`<div class="material-balance"><dt>${v.canUpgrade?'強化できます':'不足している欠片'}</dt><dd>${v.canUpgrade?'↑ 強化可能':n(v.cost-v.have)+' 個'}</dd></div>`:''}</dl><p class="small">装備枠は2つ。入手・装備・強化は一覧から操作できます。${!isStar?'固有効果はLv.1から有効で、Lv.2〜5は基礎能力の育成補正が上昇します。':''}</p></div>`;
}
function powersView(a){
 const ordered=['abyss','wing','fallen','king','judge','star'].map(id=>POWERS.find(p=>p.id===id));
 if(powerSort==='owned')ordered.sort((x,y)=>Number(!!a.powers[y.id])-Number(!!a.powers[x.id]));
 return `<div class="upgrade-powers-header"><h2>権能一覧</h2><button class="ghost" data-action="sortPowers" aria-label="権能一覧を並び替える">${powerSort==='owned'?'通常の順序':'所持優先に並び替え'}</button></div><div class="upgrade-power-grid">${ordered.map(p=>{
 const v=powerStatus(a,p),costText=!v.lv?(p.id==='star'?`実績 ${a.achieved.length}/${ACHIEVEMENTS.length}`:'入手 120 P'):v.max?'育成完了':`欠片 ${n(v.have)} / ${n(v.cost)}`;
 const action=v.lv?`${button(v.selected?'装備解除':'装備する','equipPower',p.id,'ghost equip-action')}${button(v.max?'MAX':'強化','upgradePower',p.id,'upgrade-action',!v.canUpgrade)}`:button(p.id==='star'?'解放条件':'120Pで入手',p.id==='star'?'powerDetails':'buyPower',p.id,'upgrade-action',p.id!=='star'&&a.p<120);
 return `<article class="upgrade-power-card state-${v.state} ${v.selected?'equipped':''}"><div class="upgrade-power-main"><img class="upgrade-power-art" ${p.id!=='star'?`data-authority-art="${p.id}"`: ''} src="${UPGRADE_ART[p.id]}" alt=""><div class="upgrade-power-identity"><h3>${p.name}</h3><p class="upgrade-power-level">${v.lv?'Lv.'+v.lv+' / 5':'未所持'}</p></div><button class="upgrade-power-detail" data-action="powerDetails" data-id="${p.id}" aria-label="${p.name}の詳細を見る">${uiIcon('search',19)}</button></div><div class="power-card-badges">${v.selected?'<span class="power-equipped-badge">✓ 装備中</span>':''}<span class="power-state-badge badge-${v.state}">${v.label}</span></div><div class="upgrade-power-meter" aria-label="強化レベル ${v.lv}/5"><span style="width:${v.lv*20}%"></span></div><div class="upgrade-power-cost">${costText}</div><div class="upgrade-power-actions">${action}</div></article>`;
 }).join('')}</div><div class="upgrade-info">${uiIcon('book',26)}<span><strong>権能の詳細</strong><small>虫眼鏡で現在・次レベルの効果と必要素材を比較できます。</small></span></div>`;
}
function marksView(a){return `<div class="notice">刻印は独立した3枠。所持 ${a.marks.length}/10・装備 ${a.markEquip.length}/3。権能連動型は対応する通常権能の装備が必要です。<br>旧刻印の所持・装備は引き継がれます。戦闘中の装備変更は次の戦闘から反映されます。</div><div class="grid">${MARKS.map(m=>`<section class="card power-card ${a.markEquip.includes(m.id)?'selected':''}" data-mark="${m.id}"><div class="row"><div class="emblem">${m.icon}</div><div><h3>${m.name}</h3><small>${a.markEquip.includes(m.id)?'装備中':a.marks.includes(m.id)?'所持':'未所持'}${m.power?' / '+(a.equipped.includes(m.power)?'対応権能を装備中':'対応権能が未装備'):''}</small></div></div><p>${m.effect}</p><div class="actions">${a.marks.includes(m.id)?button(a.markEquip.includes(m.id)?'装備解除':'装備する','equipMark',m.id,'primary'):button(`${m.cost}P で入手`,'buyMark',m.id,'',a.p<m.cost)}</div></section>`).join('')}</div>`;}
function resonanceView(a){return `<div class="notice">${a.cleared.includes(50)?'共鳴解放済み':'通常カイザーLv.50の撃破記録で解放'}。Lv.5権能2つを消費する永久1回の合成です。余剰欠片は共鳴片へ1:1変換。消費後も権能を120Pで再入手できます。</div><div class="grid">${RECIPES.map(r=>{const lv=a.resonance[r.id],done=a.recipes.includes(r.id),eligible=r.live&&a.cleared.includes(50)&&r.parts.every(x=>a.powers[x]===5)&&!done;return `<section class="card power-card ${a.equipped.includes(r.id)?'selected':''}"><div class="row between"><h3>◇ ${r.name}</h3><span class="tag">${lv?'Lv. '+lv:r.live?'LIVE RECIPE':'開発者専用'}</span></div><div class="small">${r.parts.map(x=>name(x)+' Lv.'+(a.powers[x]||0)).join(' ＋ ')}</div><p>${r.effect}</p><div class="effect">補完倍率：Lv.1 基礎全能力1.20倍 → Lv.5 1.68倍。現在 ${lv?(1.2+(lv-1)*.12).toFixed(2):'—'}倍。${lv&&lv<5?'次 '+(1.2+lv*.12).toFixed(2)+'倍':''}<br>強化：40 / 80 / 120 / 160共鳴片</div><div class="actions">${lv?`${button(a.equipped.includes(r.id)?'装備解除':'装備する','equipPower',r.id,'primary')}${button(lv>=5?'MAX':`強化 ${BALANCE.resCosts[lv-1]}片`,'upgradePower',r.id,'',lv>=5||a.resShards<BALANCE.resCosts[lv-1])}`:button(done?'合成済み':r.live?'共鳴する':'通常合成不可','askFuse',r.id,'',!eligible)}</div></section>`;}).join('')}</div>`;}
function trainingView(a){return `<div class="grid"><section class="card stack"><h3>いれーな育成</h3>${[['level','基礎レベル',a.level,150,40+a.level*3,'HP＋42 / 攻撃＋13 / 防御＋5 / 速度＋2'],['talent','才能',a.talent,20,a.talent*30,`攻撃補正 ${Math.round((a.talent-1)*3.5)}% → ${Math.round(a.talent*3.5)}%`],['feather','黒翼・羽弾',a.skills.feather,10,a.skills.feather*35,`技倍率 ${(1.95*(1+(a.skills.feather-1)*.07)).toFixed(2)} → ${(1.95*(1+a.skills.feather*.07)).toFixed(2)}`],['destruction','破壊の権能',a.skills.destruction,10,a.skills.destruction*35,`技倍率 ${(2.4*(1+(a.skills.destruction-1)*.1)).toFixed(2)} → ${(2.4*(1+a.skills.destruction*.1)).toFixed(2)}`],['ultimate','超堕天撃',a.skills.ultimate,10,a.skills.ultimate*35,`技倍率 ${(5.4*(1+(a.skills.ultimate-1)*.08)).toFixed(2)} → ${(5.4*(1+a.skills.ultimate*.08)).toFixed(2)}`]].map(([id,title,lv,max,cost,text])=>`<div><div class="row between"><div>${title}<small> Lv.${lv}/${max}</small><div class="small">${lv<max?text:'最大強化済み'}</div></div>${button(lv>=max?'MAX':`${cost}Pで強化`,'train',id,'',lv>=max||a.p<cost)}</div></div>`).join('')}</section><div class="stack"><section class="card"><h3>通常ステータス調整</h3><p class="small">残り ${a.sp}P / 通常Lv.100初撃破で50P、一度だけ獲得。</p>${allocations(a,false)}</section><section class="card"><h3>最終決戦専用・独立150P</h3><p class="small">残り ${a.finalBuild.points}P / 通常いれーなに影響しません。</p>${allocations(a,true)}${button('専用配分をリセット','resetFinal','','ghost small')}</section></div></div>`;}
function allocations(a,final){return `<div class="statgrid">${[['hp','HP',final?80:35],['atk','攻撃',final?35:12],['def','防御',final?22:9],['spd','速度',final?6:3]].map(([id,label,value])=>`<div><span class="small">${label} ＋${value} / ${final?a.finalBuild[id]:a.stats[id]}P</span><div>${button('＋1P',final?'allocateFinal':'allocate',id,'ghost',final?a.finalBuild.points<=0:a.sp<=0)}</div></div>`).join('')}</div>`;}
// Display tiers classify existing rewards; the original missing-first lottery is unchanged.
const SUMMON_RARITY={'黒翼の欠片':'R','深淵結晶':'R','堕天の羽根':'R','断罪の印章':'SR','王権の残光':'SR','星のかけら':'SSR'};
function summonRates(a){
 const missing=SUMMONS.filter(x=>!a.collection.includes(x)),pool=missing.length?missing:SUMMONS;
 return `<details class="summon-rates"><summary>レアリティ・現在の排出率</summary><p class="small">次の1回の確率です。10連も1枚ごとに未所持優先で再計算します。レアリティは報酬の区分で、欠片の数量や性能は変わりません。</p>${['R','SR','SSR'].map(t=>`<p><b class="rarity-${t}">${t}</b> ${(100*pool.filter(x=>SUMMON_RARITY[x]===t).length/pool.length).toFixed(2)}%</p>`).join('')}<ul>${SUMMONS.map(x=>`<li>${SUMMON_RARITY[x]} · ${x}：${pool.includes(x)?(100/pool.length).toFixed(2):'0.00'}%</li>`).join('')}</ul></details>`;
}
function summonCinema(){
 const tier=summonSession.results.reduce((best,x)=>['R','SR','SSR'].indexOf(SUMMON_RARITY[x.reward])>['R','SR','SSR'].indexOf(best)?SUMMON_RARITY[x.reward]:best,'R');
 cinema('summon',tier,{R:'黒翼に宿る記憶',SR:'深淵が呼び覚ます輝き',SSR:'天星の扉が開く'}[tier],summonPresentation,{R:1400,SR:1900,SSR:2400}[tier]);
 const el=$('#cinema');el.classList.add('summon-cinema','rarity-'+tier);
 el.querySelectorAll('.tunnel').forEach(x=>x.remove());
 const field=document.createElement('div');field.className='summon-field';field.setAttribute('aria-hidden','true');field.innerHTML=`<img class="summon-crest" src="${SCENES.fallenCrest}" alt=""><div class="summon-ring"></div><div class="summon-ring outer"></div>${Array.from({length:tier==='SSR'?12:tier==='SR'?8:4},(_,i)=>`<i class="summon-ray" style="--angle:${i*30}deg;--delay:${i*.035}s"></i>`).join('')}`;
 el.prepend(field);
}
// Rewards are committed and saved once before the presentation starts.
function summonPresentation(){
 const {results,revealed}=summonSession,done=revealed===results.length;
 modal('黒翼召喚 — 星の記憶',`<div class="summon-opening" aria-hidden="true">${uiIcon('star',48)}</div><p class="summon-progress" role="status">${done?'召喚完了':`${revealed} / ${results.length} 枚を開封`}</p><div class="summon-results">${results.map((x,i)=>i<revealed?`<article class="summon-result rarity-${SUMMON_RARITY[x.reward]} ${x.dupe?'duplicate':'discovery'}"><span class="summon-seal" aria-hidden="true">${uiIcon('gem',32)}</span><span class="summon-label">${SUMMON_RARITY[x.reward]} · ${x.dupe?'獲得済み':'NEW'}</span><strong>${esc(x.reward)}</strong><small>権能欠片 ＋8${x.dupe?'<br>共鳴片 ＋5':''}</small></article>`:`<div class="summon-result sealed" aria-label="未開封 ${i+1}枚目"><span aria-hidden="true">✦</span></div>`).join('')}</div><p class="small">報酬は獲得済みです。閉じても失われません。</p>`,done?'':button('次の1枚を開く','summonReveal','','primary')+button('すべて開く','summonAll','','ghost'));
 $('#modal').classList.add('summon-dialog');$('#modal').scrollTop=0;$('#modal').querySelector('button')?.focus({preventScroll:true});
}
function summonView(a){return `<div class="grid"><section class="card stack"><div class="tag">BLACK WING SUMMON</div><h2>黒翼に、星の記憶を。</h2><div class="summon-sanctuary"><img src="${HOME_CARD_ART.summon}" alt="黒翼召喚の祭壇"><span>失われた記憶を、翼に。</span></div><p class="small">未所持を優先：未所持N種類から各1/Nの等確率。全6種収集後は各1/6。各報酬で権能欠片8個、重複時は共鳴片＋5。（排出仕様は補完）</p><div class="row">${button('単発 25P','summon','1','primary',a.p<25)}${button('10連 250P','summon','10','primary',a.p<250)}</div>${summonRates(a)}<div class="summon-wallet"><span>所持 <strong>${n(a.p)} P</strong></span><span>図鑑 <strong>${a.collection.length} / 6</strong></span></div><progress class="summon-collection-progress" max="6" value="${a.collection.length}" aria-label="召喚図鑑の収集状況"></progress><p class="small">通算 ${a.summons}回 · ${a.collection.length===6?'全種類収集済み。重複で共鳴片を獲得':'未収集の記憶を優先して獲得'}</p></section><section class="card"><h3>召喚図鑑</h3><div class="stack" style="margin-top:16px">${SUMMONS.map((x,i)=>`<div class="equip"><div class="emblem">${['✧','◈','⚖','♜','♛','✺'][i]}</div><div><strong>${a.collection.includes(x)?x:'？？？'}</strong><small>${SUMMON_RARITY[x]} · ${a.collection.includes(x)?'COLLECTED':'未収集'}</small></div></div>`).join('')}</div></section></div><div class="section-head"><h2>召喚履歴</h2><small>最新60件</small></div><section class="card"><div class="collection">${a.summonHistory.length?a.summonHistory.map(x=>`<span>${x.reward}${x.dupe?' / 共鳴片＋5':' / NEW'}</span>`).join(''):'まだ星の記憶はありません。'}</div></section>`;}
function enemyArt(b){if(b.campaign&&['normal','ex'].includes(b.mode))return `<img class="sprite portrait enemy-portrait" src="${CAMPAIGN_ART[b.mode]}" alt="${b.mode==='ex'?'EXカイザー':'カイザー'}の提供透過立ち絵">`;const src=ENEMIES[b.mode];if(src)return `<img class="sprite portrait enemy-portrait" src="${src}" alt="${b.mode==='ex'?'EXカイザー':'通常カイザー'}のユーザー提供立ち絵">`;return `<svg class="sprite" viewBox="0 0 280 260" aria-label="カイザーの代替紋章" role="img"><defs><radialGradient id="eg"><stop stop-color="#803b6255"/><stop offset="1" stop-color="#120d1a00"/></radialGradient><linearGradient id="eb" x2="0" y2="1"><stop stop-color="#7c586d"/><stop offset="1" stop-color="#201728"/></linearGradient></defs><ellipse cx="140" cy="130" rx="125" ry="120" fill="url(#eg)"/><g stroke="#88674d" fill="none" opacity=".5"><circle cx="140" cy="120" r="83"/><circle cx="140" cy="120" r="100" stroke-dasharray="1 9"/></g><path d="m119 83-49-66 20 85-53-34 41 61-56 32 73 7-25 62 58-35 13 39 18-39 58 35-25-62 73-7-56-32 41-61-53 34 20-85-49 66Z" fill="#251e30" stroke="#8c6877"/><path d="m93 91 47-29 47 29 8 58-55 47-55-47Z" fill="url(#eb)" stroke="#b68f6d"/><path d="m93 102 47 20 47-20-15 37-32-9-32 9Z" fill="#15121c"/><path d="m107 114 27 10-24 3Zm66 0-27 10 24 3Z" fill="#ee8798"/><path d="m140 85-9 55 9 38 9-38Z" fill="#302433" stroke="#ac8079"/><path d="m110 150 23 4-7 19m44-23-23 4 7 19" stroke="#cca67a" fill="none"/><path d="m108 63 7-25 25 17 25-17 7 25-32-11Z" fill="#ac8359"/></svg>`;}
function irenaCommands(b){return [['slash','斬撃','通常攻撃 / ゲージ＋26','⚔'],...(b.marks.includes('split')?[['pierce','穿羽','羽弾1.3倍 / CT3','↟'],['volley','連羽','0.7倍 × 2 / CT2','⋈']]:[['feather','黒翼・羽弾','1.95倍 / ゲージ＋39','✦']]),['power','破壊の権能','装備権能で攻撃 / CT3','◈'],['ultimate','超堕天撃','5.4倍 / ゲージ100%消費','✺'],['guard','防御',b.trial||b.campaign?'軽減70%・ゲージ＋18・HP12%回復':'被ダメージ70%軽減 / ゲージ＋18','⬡']];}
function battleView(a){if(!battle)return `${heading('王への挑戦','一撃を研ぎ澄ませ、百の玉座を越えよ。','KAISER / CONQUEST')}<section class="card stack"><h2>通常カイザー</h2><div class="selectline"><label>挑戦Lv. <input id="floor" type="number" min="1" max="${a.floor}" value="${Math.min(selectedFloor,a.floor)}"></label><label>難易度 <select id="difficulty"><option ${difficulty==='NORMAL'?'selected':''}>NORMAL</option><option ${difficulty==='EXPERT'?'selected':''}>EXPERT</option></select></label>${button('戦闘開始 →','fight','selected','primary')}</div><p class="small">最高到達 Lv.${a.floor} / 初回突破で次階層と基礎レベルが進行。再戦でもPと欠片を獲得できます。EXPERTは敵HP1.3倍・攻撃1.2倍・速度1.1倍（補完）。</p>${a.flags.lv100&&!a.flags.stella?button('？？？？？','warp','','primary'):''}</section><div class="section-head"><h2>異界の戦場</h2></div><div class="grid triple home-modes">${modeCard('◈','深淵レイド','共鳴片と育成資源を獲得','raid',a.cleared.includes(50),'通常Lv.50撃破')}${modeCard('♛','EX カイザー','全基礎能力2倍の三形態','ex',a.flags.stella,'ステラ解放後')}${modeCard('✧','ステラ最終決戦','終焉のカイザー HP30,000','stella',a.flags.stella,'ステラ解放後')}${modeCard('✺','いれーな最終決戦','神化・堕天の選択','final',a.flags.final,'ステラ最終決戦クリア')}${modeCard('⬡','神域連戦','五柱の神を越える','god',a.flags.ex,'EXカイザー撃破')}</div>`;
 const b=battle,p=playerStats(b),e=enemyStats(b);let skills=b.character==='irena'?irenaCommands(b):b.character==='stella'?[['slash','星の斬撃','ステラの通常攻撃','✧'],['immortal','不滅','発動ターン完全無敵 / CT4','◇'],['rebirth','再誕',`最大HP${[100,50,25][b.rebirths]||0}%回復 / 残り${3-b.rebirths}回`,'❀'],['meteor','天象支配',b.meteor?'使用済み':'隕石5,000 / 1戦闘1回','✺'],['guard','防御','被ダメージ70%軽減','⬡']]:[['slash','斬撃','専用いれーなの通常攻撃','⚔'],['guard','防御','被ダメージ70%軽減','⬡'],['divine','神化','＋15 / 攻撃せず1ターン使用','✧'],['fallen','堕天','−15 / 攻撃せず1ターン使用','♜'],...Object.entries(FINAL_SKILLS).map(([id,x])=>[id,x.name,x.text,x.side===-1?'♜':x.side===1?'✧':'◈']),['genesis','創世','＋100 / 神威・静寂・再臨','✺'],['ending','終焉','−100 / 崩壊・断絶・消滅','✺']];
 if(b.statuses.stun)skills=[['wait','反動から復帰','このターンは行動できません','⌛']];
 if(b.character==='final')skills=skills.filter(([id])=>!available(b,id));
 const playerName=b.character==='stella'?'ステラ':b.character==='final'?'いれーな・最終決戦':'いれーな';
 return `${heading(b.character==='irena'?({normal:'カイザー戦',ex:'EXカイザー戦',raid:'深淵レイド',god:'神域連戦'}[b.mode]||'カイザー戦'):'境界の戦い',`${b.test?'試験戦闘 / ':''}${b.mode==='normal'?'通常攻略':{ex:'EXカイザー',raid:'深淵レイド',stella:'ステラ最終決戦',final:'いれーな最終決戦',god:'神域連戦'}[b.mode]} / ${b.difficulty}`,(b.character==='irena'?'TURN ':'BATTLE / TURN ')+b.turn)}${!b.result?`<div class="combat-shortcuts" aria-label="戦闘画面の移動">${button('戦場へ','focusStage','','ghost')}${button('技を選ぶ ↓','focusCommands','','primary')}</div>`:''}<div class="battle-layout"><div><section ${b.campaign&&b.character==='irena'?`style="--campaign-background:url('${CAMPAIGN_ART.background}')"`:''} class="battle-stage ${b.campaign&&b.character==='irena'?'campaign-stage':''} ${b.character==='final'?(b.balance===0?'stage-neutral':b.balance>0?'stage-divine':'stage-fallen'):b.character==='stella'?'stage-stella':''}"><div class="fighter fighter-player"><h3>${playerName}</h3><div class="portrait-frame"><img class="sprite portrait ${b.character==='irena'?'portrait-alpha':''}" src="${battlePortrait(b)}" alt="${playerName}の戦闘立ち絵"></div><div class="info"><div class="row between" style="gap:4px"><span>HP</span><span class="hpnum">${n(p.current)} / ${n(p.hp)}</span></div><div class="health player"><span style="width:${p.ratio*100}%"></span></div><small>${b.character==='irena'?`致死耐性 ${b.lives} / 不屈 ${b.markLife}`:b.character==='stella'?`再誕 残り${3-b.rebirths}回`:`${b.balance>=0?'神化':'堕天'} 段階 ${stage(b.balance)}`}</small></div></div><div class="fighter fighter-enemy"><h3>${b.enemy.name}</h3><div class="portrait-frame portrait-foe ${ENEMIES[b.mode]?'supplied-enemy':''}">${enemyArt(b)}</div><div class="info"><div class="row between" style="gap:4px"><span>HP</span><span class="hpnum">${n(b.enemy.hp)} / ${n(e.hp)}</span></div><div class="health"><span style="width:${Math.max(0,b.enemy.hp/e.hp*100)}%"></span></div><small>第${b.enemy.phase}形態 / 侵食 ${Math.round(b.erosion*100)}%</small>${b.campaign?`<small class="actual-enemy-state">${b.enemy.statuses.campaignArmor?'黒晶殻 ':''}${b.enemy.statuses.campaignSever?'権能の傷痕':''}</small>`:''}${b.trial?`<small class="actual-enemy-state">${b.enemy.statuses.trialCrystal?'黒晶殻':''}${b.enemyStop?' ／ 震撼':''}</small>`:''}</div></div></section>${b.character==='irena'?`<section class="card battle-charge" style="padding:12px 18px;margin-top:12px"><div class="row between"><small>必殺ゲージ</small><span class="gold">${b.gauge}%</span></div><div class="gaugebar"><span style="width:${b.gauge}%"></span></div></section>`:b.character==='final'?`<section class="card" style="padding:12px 18px;margin-top:12px"><div class="row between"><small>堕天 −100</small><span class="gold">${b.balance>0?'+':''}${b.balance}</span><small>神化 ＋100</small></div><div class="balancebar"><i style="left:${(b.balance+100)/2}%"></i></div><div class="gauge-stages"><span class="${stage(b.balance)>=1?'reached':''}">I · 30</span><span class="${stage(b.balance)>=2?'reached':''}">II · 60</span><span class="${stage(b.balance)>=3?'reached':''}">III · 100</span></div></section>`:''}${b.result?resultView(a,b):`<div class="battle-controls ${b.character==='final'?'final-commands':''}">${skills.map(([id,title,desc,glyph])=>{const reason=available(b,id),clean=b.character==='final',art=clean?MEDIA.fallenSkills[id]:null;return `<button class="skill ${['ultimate','genesis','ending','annihilate'].includes(id)?'ultimate':''}" data-action="combat" data-id="${id}" ${reason?'disabled':''} aria-label="${esc(title)}" ${clean?'':`title="${esc(reason||desc)}"`}><span class="glyph ${art?'has-art':''}">${art?`<img class="skill-art" src="${art}" alt="" width="58" height="58">`:clean?uiIcon(({slash:'swords',guard:'shield',divine:'star',fallen:'crown',godspeed:'power',omnipotent:'crown',dominion:'star',annihilate:'gem',transcend:'shield',grasp:'target',genesis:'star',wait:'shield'})[id]||'gem',26):glyph}</span><span><strong>${title}${!clean&&b.cd[id]>0?'　CT '+b.cd[id]:''}</strong>${clean?'':`<small>${reason||desc}</small>`}</span></button>`;}).join('')}</div>`}</div><aside class="battle-aside stack"><section class="card ${b.character==='irena'?'combat-status-card':''}"><h3>${b.character==='irena'?'権能・現在の状態':'戦況と権能'}</h3>${b.character==='irena'?'<details class="battle-details"><summary>能力値を確認</summary>':''}${statsHTML(p)}<div class="small">敵：攻 ${n(e.atk)} / 防 ${n(e.def)} / 速 ${n(e.spd)}</div>${b.character==='irena'?'</details>':''}${!b.result&&b.enemy.phase===3&&['ex','final'].includes(b.mode)?`<div class="notice" style="margin:14px 0 0">終末判定まで ${Math.max(0,9-b.phaseTurns)}ターン<br>通常行動の停止では防げません。</div>`:''}<div class="statuslist">${b.powers.map(id=>`<span class="pill">${name(id)}${['judge','judgewing','kingjudge','fallenjudge','abyssjudge'].includes(id)?' '+(b.stacks[id]||0)+'/2':''}</span>`).join('')}${b.buffs.map(x=>`<span class="pill gold">${FINAL_SKILLS[x.id]?.name||{divineMight:'神威',godlow:'堕天の神',grasp:'理外掌握',trialFocus:'蓄勢',campaignFocus:'蓄勢'}[x.id]||x.id} ${x.remaining>900?'∞':x.remaining+'T'}</span>`).join('')}${Object.entries(b.statuses).map(([k,v])=>`<span class="pill">${{stun:'行動不能',seal:'封印',invulnerable:'無敵',pressure:'重圧',slow:'速度低下',fragile:'防御半減'}[k]||k} ${v}T</span>`).join('')}${b.ignoreDefense?`<span class="pill">崩壊 ${b.ignoreDefense}T</span>`:''}${b.noBuff?`<span class="pill">断絶 ${b.noBuff}T</span>`:''}${b.noPressure?`<span class="pill">重圧無効 ${b.noPressure}T</span>`:''}</div></section><section class="card ${b.character==='irena'?'combat-record':''}">${b.character==='irena'?`<p class="last-event" aria-live="polite">${esc(b.log.at(-1)||'戦闘を開始しました')}</p><details class="battle-log"><summary>戦闘記録を開く</summary>`:'<div class="row between" style="margin:0 0 12px"><h3>戦闘記録</h3><span class="tag">COMBAT LOG</span></div>'}<div class="log" aria-live="polite">${[...b.log].reverse().map(x=>`<p>${esc(x)}</p>`).join('')}</div>${b.character==='irena'?'</details>':''}</section>${!b.result?button('撤退する','askRetreat','','ghost'):''}</aside></div>`;
}
function resultView(a,b){if(b.campaign)return campaignResult(campaign,b,button);
 const victoryArt=b.result==='win'&&b.mode==='normal',r=b.reward||{},won=b.result==='win';
 const unlockNames={fallen:'権能「堕天」',king:'権能「堕天王」',judge:'権能「断罪」',star:'天星覇権 Lv.5',resonance:'権能共鳴',raid:'深淵レイド',mystery:'？？？？？ — 境界への扉',god:'神域連戦',final:'最終決戦専用いれーな'};
 const earned=!b.test&&won?`<div class="reward-grid" aria-label="今回の獲得報酬"><div><small>育成ポイント</small><strong data-reward="p">＋${n(r.p||0)}<em>P</em></strong>${r.bonusP?`<span data-reward="bonusP">初回報酬 ＋${n(r.bonusP)}P を含む</span>`:''}</div><div><small>各権能の欠片</small><strong data-reward="fragments">＋${n(r.fragments||0)}</strong></div><div><small>共鳴片</small><strong data-reward="resShards">＋${n(r.resShards||0)}</strong></div>${r.levels?`<div class="reward-growth"><small>基礎レベル</small><strong data-reward="levels">＋${n(r.levels)} Lv.</strong></div>`:''}${r.sp?`<div class="reward-growth"><small>ステータスポイント</small><strong data-reward="sp">＋${n(r.sp)}P</strong></div>`:''}</div>`:'';
 const discoveries=!b.test?`${r.unlocks?.length?`<div class="result-discoveries"><small>新たに取り戻した力</small>${r.unlocks.map(id=>`<strong data-unlock="${id}">✧ ${unlockNames[id]||esc(id)}</strong>`).join('')}</div>`:''}${r.achievements?.length?`<div class="result-achievements"><small>実績達成 · ${r.achievements.length}件</small>${r.achievements.map(id=>`<span data-achievement="${id}">${esc(ACHIEVEMENTS.find(x=>x.id===id)?.name||id)}</span>`).join('')}${button('実績の報酬を受け取る →','nav','archive','ghost')}</div>`:''}`:'';
 const nextMilestone=won&&b.mode==='normal'&&!b.test?[[5,'権能「堕天」'],[10,'権能「堕天王」'],[20,'権能「断罪」'],[50,'共鳴・深淵レイド'],[100,'境界への扉']].find(([floor])=>!a.cleared.includes(floor)):null;
 return `<section class="result ${victoryArt?'result-illustrated':''}">${victoryArt?`<img class="result-art" src="${SCENES.victory}" alt="通常戦闘の勝利イラスト">`:''}<div class="result-content"><div class="tag">${b.test?'TEST RESULT':'BATTLE RESULT'}</div><h2>${won?'VICTORY':'DEFEAT'}</h2><p class="small">${b.test?'試験戦闘のため本編報酬・実績には反映しません。':won?'失われた力を、またひとつ取り戻した。':'育成を整え、技と装備を組み替えて再挑戦できます。'}${b.mode==='god'&&!won?'<br>今回の仮獲得素材と連戦進行を破棄しました。':''}</p>${earned}${discoveries}${nextMilestone?`<p class="result-next">次の節目：カイザー Lv.${nextMilestone[0]} 撃破で ${nextMilestone[1]}</p>`:''}${r.unlocks?.includes('mystery')?button('？？？？？ — 境界を越える','warp','','primary full'):''}<div class="row" style="justify-content:center">${button('聖域に戻る','finish','','ghost')}${button(won&&b.mode==='normal'&&b.floor<100?'次の階層へ':b.mode==='god'&&a.gauntlet?'次の神へ':'再挑戦','retry','','primary')}</div></div></section>`;
}
function archive(a){return `${heading('戦いの記憶','全36実績で、天星覇権 Lv.5を取り戻す。','ARCHIVE / ACHIEVEMENTS')}<div class="notice">達成 ${a.achieved.length}/36 / 受取 ${a.claimed.length}件。各実績60Pは手動で1回受取。条件の原本は未回収のため、提供された復元一覧を採用しています。</div><div class="grid triple">${[['A','火力','与ダメージ1.05 / 1.09 / 1.12倍'],['B','技巧','特殊1.08 / 1.12 / 1.15倍、必殺最大1.12倍'],['C','均衡','HP1.05 / HP防1.07 / 全能力1.12倍＋被ダメ0.92倍']].map(([cat,title,text])=>{const rank=badgeRank(a,cat),count=ACHIEVEMENTS.filter(x=>x.cat===cat&&a.achieved.includes(x.id)).length;return `<section class="card"><div class="row between"><span class="badge">${{A:'⚔',B:'✧',C:'⬡'}[cat]}</span><span class="tag">${count} / 12</span></div><h3>${title}の徽章 ${['—','I','II','III'][rank]}</h3><p class="small">3 / 5 / 8個で自動進化。${text}</p><div class="row">${button(a.badge===cat?'装備解除':'装備する','badge',cat,'ghost',!rank)}</div></section>`;}).join('')}</div>${['A','B','C'].map(cat=>`<div class="section-head"><h2>${{A:'A — 火力',B:'B — 技巧',C:'C — 均衡'}[cat]}</h2><span class="tag">12 RECORDS</span></div><div class="grid">${ACHIEVEMENTS.filter(x=>x.cat===cat).map(x=>`<section class="card achievement ${a.achieved.includes(x.id)?'':'locked'}"><div class="emblem">${a.achieved.includes(x.id)?'✧':'◇'}</div><div><h3>${x.name}</h3><p>${x.detail}</p></div>${button(a.claimed.includes(x.id)?'受取済':a.achieved.includes(x.id)?'60P 受取':'未達成','claim',x.id,'',!a.achieved.includes(x.id)||a.claimed.includes(x.id))}</section>`).join('')}</div>`).join('')}`;}
function awakeningView(a){return `${heading('失われた神格','新たな力ではない。かつての自分を、取り戻す。','DIVINE / REAWAKENING')}<div class="grid"><section class="card"><div class="tag">STAGE ${a.awakening} / 5</div><h2>${AWAKENINGS[a.awakening]}</h2><img class="awakening-art" src="${MEDIA.keyArt}" alt="ユーザー提供の共通キービジュアル（覚醒段階別ではありません）"><div class="levelsteps">${Array.from({length:5},(_,i)=>`<i class="${i<a.awakening?'on':''}"></i>`).join('')}</div><p class="small">各段階で通常基礎能力＋18%（補完）。共通キービジュアルを表示しています。5段階の専用絵とMP4は未提供です。</p></section><div class="stack"><section class="card"><h3>神格を取り戻す</h3><p class="small">共通神素材 ${a.godMaterials} / 神域の勲章 ${a.medals}<br>固有素材：${GODS.map((x,i)=>x+' '+a.godUnique[i]).join(' / ')}</p><p>${a.awakening<5?`次：${AWAKENINGS[a.awakening+1]}<br><span class="small">共通素材 ${(a.awakening+1)*5} ＋ ${GODS[a.awakening]}の固有素材1</span>`:'神格は完全に再生された。'}</p><div class="row">${button('手動で覚醒する','awaken','','primary',a.awakening>=5||a.godMaterials<(a.awakening+1)*5||a.godUnique[a.awakening]<1)}</div></section><section class="card"><h3>神域連戦</h3><p class="small">EX撃破後に解放。固定5連戦・各戦全回復。素材は全突破まで仮獲得。敗北・撤退で今回の進行と素材を失います。</p>${a.gauntlet?`<p>第${a.gauntlet.index+1}戦 / 仮素材 ${a.gauntlet.materials}</p>`:''}<div class="row">${button(a.gauntlet?'連戦を続ける':'神域へ挑戦','fight','god','ghost',!a.flags.ex)}</div></section><section class="card"><h3>第5段階の演出基盤</h3><p class="small">専用MP4の再生に対応。現在は10秒のCSS代替演出を使用します。元の覚醒ムービーではありません。</p>${button('代替演出をプレビュー','movie','','ghost')}</section></div></div>`;}
function lab(a){return `${campaignEntry(campaign,button)}${heading('境界の実験場','本編の保存データから独立した、戦闘検証空間。','EXPERIMENT / SANDBOX')}<div class="notice">ここで始めた戦闘はすべて試験扱いです。報酬、実績、通常の解放フラグを更新しません。</div><section class="card stack"><h2>戦闘パラメータ</h2><div class="selectline"><label>モード<select id="labmode"><option value="normal">通常いれーな</option><option value="ex">EXカイザー</option><option value="three-phase">EXカイザー・三相決戦【試作】</option><option value="stella">ステラ</option><option value="final">最終決戦いれーな</option></select></label><label>基礎攻撃倍率 <input id="labatk" type="number" value="1" min="0.1" max="20" step=".1"></label><label>基礎HP倍率 <input id="labhp" type="number" value="1" min="0.1" max="20" step=".1"></label></div><p class="small">全育成状態の試験キャラクターを使用。倍率はこの戦闘だけに適用します。三相決戦は黒翼＋堕天王の固定ビルドで開始。第二相から敵が硬化・重圧・回復を発動。破壊の権能・必殺で黒晶殻を解除、防御で重圧を解除、HP12%を回復して蓄勢を獲得。蓄勢は斬撃・破壊の権能を一回強化します。数値は実験用です。</p>${button('独立試験を開始','labstart','','primary')}</section><div class="section-head"><h2>計算仕様</h2></div><section class="card"><p class="small">基本ダメージ = max(1, 攻撃×技倍率 − 防御×(1−無視率)) × 最終補正 ＋ 現在HP追加。最低保証は最後に適用。低HP倍率は排他的。深淵は基礎値から毎ターン6%の線形減少、下限5%。<br>堕天によるHP倍率は内部の生命割合を維持するため、倍率切替だけでは回復しません。羽弾と断罪の乗算・追加は別枠です。</p></section>`;}
function dev(a){return `${heading('観測者の書架','全機能を検証するための、独立した試験用セーブ。','DEVELOPER / CONTROL')}<div class="notice">「全機能開放」は本編のコピーから試験データを作成します。テスト戦の勝利は実績・初回報酬を付与しません。本編へ戻ると元の進行をそのまま再開できます。天星覇権はここでも36実績条件を維持します。</div><section class="card"><h2>全機能開放</h2><p class="small">全階層、ステラ、EX、最終決戦、共鳴10種、刻印、育成・素材を開放。試験用セーブは独立キーに保存。</p><div class="row">${button(sandbox?'試験データを再作成':'全機能開放','enabledev','','primary')}${sandbox?button('本編へ戻る','exitdev','','ghost'):button('保存済み試験データを開く','resumedev','','ghost')}</div>${sandbox?`<div class="dev-buttons">${[['normal','通常Lv.100'],['ex','EXカイザー'],['stella','ステラ最終決戦'],['final','専用いれーな'],['god','神域連戦']].map(([id,title])=>button(title,'fight',id)).join('')}</div>`:''}</section><div class="section-head"><h2>セーブ管理</h2></div><section class="card"><div class="row">${button('JSONバックアップ','export','','ghost')}${button('JSONを読み込む','import','','ghost')}${button('タイトルへ','title','','ghost')}${button('本編を初期化','askReset','','danger')}</div><p class="footnote">保存キー：irena-reborn-v3 / 旧v1・v2キーも検索。未知の旧スキーマは推測して変換せず、エラーを表示します。</p></section>`;}
function tone(kind='hit'){if(!sound)return;try{audio ||= new (window.AudioContext||window.webkitAudioContext)();audio.resume();const osc=audio.createOscillator(),g=audio.createGain();osc.connect(g);g.connect(audio.destination);osc.type=kind==='ultimate'?'sawtooth':'sine';osc.frequency.setValueAtTime(kind==='ultimate'?330:620,audio.currentTime);osc.frequency.exponentialRampToValueAtTime(80,audio.currentTime+.18);g.gain.setValueAtTime(.05,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.22);osc.start();osc.stop(audio.currentTime+.25);}catch{sound=false;}}
function cinema(type,title,sub,done,duration=2400,art=null){
 if(combatAnimating)return;
 const el=$('#cinema');let completed=false;
 const finish=()=>{if(completed)return;completed=true;clearTimeout(cinemaTimer);el.className='';el.innerHTML='';el.setAttribute('aria-hidden','true');try{done?.();}finally{combatAnimating=false;syncCombatBusy();}};
 combatAnimating=true;syncCombatBusy();
 el.className='active '+(type==='cut'?'cut':'');el.setAttribute('aria-hidden','false');
 el.innerHTML=`${type==='cut'?`<img src="${art||MEDIA.keyArt}" alt="${esc(title)}の演出画像">`:'<div class="tunnel"></div><div class="tunnel"></div><div class="tunnel"></div>'}<div class="cinema-copy"><h2>${title}</h2><p>${sub}</p></div><button id="skipCinema" type="button">スキップ</button>`;
 $('#skipCinema').onclick=finish;$('#skipCinema').focus({preventScroll:true});
 cinemaTimer=setTimeout(finish,matchMedia('(prefers-reduced-motion: reduce)').matches?50:duration);
}
// The alignment pause delays the actual turn (including enemy response) by 200 ms.
// Skip commits once immediately. None of these animations change combat calculations.
function syncCombatBusy(){
 const busy=combatAnimating||(typeof combatRecovering!=='undefined'&&combatRecovering);
 if(document.documentElement?.dataset)document.documentElement.dataset.combatBusy=String(busy);
 const app=$('#app');if(app)app.inert=busy;
 const controls=$('.battle-controls');controls?.setAttribute?.('aria-busy',String(busy));
}
function alignmentShift(id){
 const reason=available(battle,id);if(reason)throw Error(reason);if(combatAnimating)return;
 const fallen=id==='fallen',el=$('#cinema'),title=fallen?'堕天':'神化';let committed=false,finished=false;
 const commit=()=>{if(committed)return;committed=true;el.classList.add('revealed');doCombat(id);};
 const finish=()=>{if(finished)return;finished=true;clearTimeout(alignmentRevealTimer);clearTimeout(cinemaTimer);try{commit();}finally{el.className='';el.innerHTML='';el.setAttribute('aria-hidden','true');combatAnimating=false;syncCombatBusy();}};
 combatAnimating=true;syncCombatBusy();el.className='active alignment '+(fallen?'alignment-fallen':'alignment-divine');el.setAttribute('aria-hidden','false');
 el.innerHTML=`<div class="alignment-tint"></div><img class="alignment-crest" src="${fallen?SCENES.fallenCrest:SCENES.divineCrest}" alt="${title}の紋章"><img class="alignment-portrait" src="${fallen?PORTRAITS.fallen:PORTRAITS.divine}" alt="${title}の立ち絵"><div class="alignment-title">${title}</div><button id="skipCinema" type="button">スキップ</button>`;
 $('#skipCinema').onclick=finish;$('#skipCinema').focus?.({preventScroll:true});
 const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 alignmentRevealTimer=setTimeout(commit,reduced?0:200);
 cinemaTimer=setTimeout(finish,reduced?100:850);
}
const STRIKE_ACTIONS=new Set(['slash','feather','pierce','volley','power','ultimate','meteor','annihilate','genesis','ending']);
function showBladeStrike(id){
 if(!STRIKE_ACTIONS.has(id))return;
 const stage=$('.battle-stage');if(!stage)return;
 const strike=document.createElement('div');strike.className='blade-strike';strike.setAttribute('aria-hidden','true');
 strike.innerHTML='<svg viewBox="0 0 100 100" preserveAspectRatio="none"><path class="blade-halo" d="M 6 84 Q 48 45 94 18"/><path class="blade-core" d="M 6 84 Q 48 45 94 18"/><path class="blade-second" d="M 21 92 Q 66 57 88 12"/></svg>';
 stage.append(strike);setTimeout(()=>strike.remove(),650);
}
// Present only combat results already calculated by gameCore. Visual effects never mutate battle state.
function showCombatFeedback(b){
 const arena=$('.battle-stage');if(!arena)return;
 const hits=b.events.filter(x=>x.type==='hit'),foe=arena.querySelector('.fighter-enemy'),player=arena.querySelector('.fighter-player');
 const numbers=(fighter,value,kind)=>{if(!fighter)return;const pop=document.createElement('span');pop.className='combat-number '+kind;pop.setAttribute('aria-hidden','true');pop.textContent=value;fighter.append(pop);setTimeout(()=>pop.remove(),920);};
 const recoil=(fighter,kind)=>{if(!fighter)return;fighter.classList.add(kind);setTimeout(()=>fighter.classList.remove(kind),520);};
 if(b.lastDamage>0){numbers(foe,n(b.lastDamage),'damage-dealt');recoil(foe,'impact-foe');}
 else if(hits.length&&hits.every(x=>x.damage===0))numbers(foe,'MISS','damage-missed');
 if(b.enemyDamage>0){numbers(player,'−'+n(b.enemyDamage),'damage-taken');recoil(player,'impact-player');}
}
function beginFight(mode,options={}){const a=current();if(battle&&!battle.result)throw Error('進行中の戦闘があります。先に戦闘画面から撤退してください。');if(mode==='god'&&!a.gauntlet)startGauntlet(a);const floor=options.floor??(mode==='normal'?a.floor:100);battle=startBattle(a,{mode,floor,difficulty:mode==='normal'?difficulty:'NORMAL',test:!!sandbox,...options});selectedFloor=floor;page='battle';persist();render();window.scrollTo(0,0);}
function doCombat(id,route='A'){
 const b=battle;if(!b||b.result)return;
 combatRecovering=true;clearTimeout(combatReleaseTimer);syncCombatBusy();
 try{
  const previousPhase=b.enemy.phase;if(b.campaign)actCampaign(b,id,{route});else if(b.trial)actThreePhase(b,id,{route});else act(b,id,{route});b.lastAction=id;
  if(b.result){b.reward=b.campaign?settleCampaign(campaign,b):settle(current(),b);if(!b.test&&b.result==='win'&&id==='ultimate'&&b.used.marks.includes('starfall')){current().records.starfinish=true;achievements(current());}if(!b.campaign&&(!b.test||sandbox))persist();}
  if(!b.result&&!b.test&&b.character==='irena')persist();
  tone(['ultimate','meteor','annihilate','genesis','ending'].includes(id)?'ultimate':'hit');render();
  if(b.events.some(x=>x.type==='hit')||b.lastDamage>0)showBladeStrike(id);showCombatFeedback(b);
  if(b.trial&&!b.result&&b.enemy.phase>previousPhase){const active=b;setTimeout(()=>{if(battle!==active||battle.result)return;cinema('cut',b.enemy.phase===3?'第三相・終極':'第二相・変転','EX KAISER · THREE PHASE',null,850,ENEMIES.ex);$('#cinema').classList.add('phase-transition');},0);}
 }finally{
  syncCombatBusy();
  combatReleaseTimer=setTimeout(()=>{combatRecovering=false;syncCombatBusy();},matchMedia('(prefers-reduced-motion: reduce)').matches?60:280);
 }
}
function download(filename,content,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function importFile(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const file=input.files[0];if(!file)return;if(file.size>2000000)throw Error('ファイルが大きすぎます（上限2MB）');const data=validateSave(JSON.parse(await file.text()));modal('セーブを復元',`<p>Lv.${data.level} / 到達Lv.${data.floor} / ${data.achieved.length}実績のデータです。${sandbox?'試験用':'本編'}セーブを上書きします。読み込み前のバックアップを書き出せます。</p>`,button('現在のJSONを書き出し','export','','ghost')+button('このデータに置き換える','confirmImport','','primary'));$('#modal').querySelector('[data-action="confirmImport"]').onclick=event=>{event.stopPropagation();if(battle&&!battle.result){toast('進行中の戦闘を撤退してから読み込んでください');return;}if(sandbox)sandbox=data;else s=data;saveBlocked=false;battle=sandbox?null:restoreMarkBattle(s.markBattle,validateSave);page='home';const stored=persist();close();render();toast(stored?'JSONから復元しました':'JSONを読み込みましたが、端末への保存に失敗しました。JSONバックアップを保持してください。');};}catch(e){toast('読み込み失敗：'+e.message);}};input.click();}
async function handle(action,id){if(combatAnimating||combatRecovering)return;const a=current();switch(action){
 case 'begin':if(saveBlocked){confirmDialog('読み込めない既存セーブがあります','新しい旅を始めると保存済みデータを上書きします。既存のデータを残す場合は閉じて、正しいJSONを読み込んでください。','newAfterError','');break;}a.started=true;persist();render();break;
 case 'newAfterError':saveBlocked=false;s=fresh();s.started=true;persist();close();render();break;
 case 'nav':if(id==='upgrade')tab='overview';page=id;render();window.scrollTo(0,0);break;
 case 'openupgrade':page='upgrade';tab=id;render();window.scrollTo(0,0);break;
 case 'upgradeBack':tab='overview';render();window.scrollTo(0,0);break;
 case 'sortPowers':powerSort=powerSort==='default'?'owned':'default';render();break;
 case 'powerDetails':{const power=POWERS.find(x=>x.id===id);if(!power)throw Error('権能が見つかりません');modal(power.name,powerDetails(a,power));break;}
 case 'tab':tab=id;render();break;
 case 'focusCommands':$('.battle-controls')?.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});break;
 case 'focusStage':$('.battle-stage')?.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});break;
 case 'sound':sound=!sound;if(sound)tone();render();break;
 case 'about':modal('いれーな REBORN',`<p>本作は提供仕様書を基準とする新規復元版です。元のHTML・JSON・画像はこの環境では取得できていません。</p><p>まず通常カイザーを倒して育成。Lv.50で共鳴とレイド、Lv.100後の「？？？？？」からステラを解放します。ステラ解放でEXに挑戦でき、ステラ最終決戦の勝利で専用いれーなが解放されます。</p><p>確定した権能倍率・専用技・実績36件は維持。敵の基礎値・経済・権能Lv成長・共鳴の未回収値・神域ボスは補完設計です。ホームのキービジュアルと堕天の技アイコンはユーザー提供画像です。未提供の立ち絵は代替SVGを使用しています。</p><p>自動保存に加え、定期的にJSONを書き出してください。戦闘中の一時状態は再起動でリセットされます。Safari実機は未確認です。音は任意の合成SEのみ。</p>`);break;
 case 'close':close();break;
 case 'equipPower':equip(a,id,'power');persist();render();break;
 case 'equipMark':equip(a,id,'mark');persist();render();break;
 case 'buyPower':buyPower(a,id);persist();render();toast(name(id)+'を取り戻した');break;
 case 'upgradePower':upgradePower(a,id);persist();render();tone();break;
 case 'buyMark':buyMark(a,id);persist();render();break;
 case 'askFuse':confirmDialog('権能共鳴',`${name(id)}を合成します。元権能2つを消費・装備解除します。余剰欠片は共鳴片に変換。このレシピは再使用できません。`,'fuse',id);break;
 case 'fuse':fuse(a,id);persist();close();render();toast(name(id)+'が共鳴した');break;
 case 'train':train(a,id);persist();render();break;
 case 'allocate':allocate(a,id);persist();render();break;
 case 'allocateFinal':allocate(a,id,true);persist();render();break;
 case 'resetFinal':a.finalBuild={points:150,hp:0,atk:0,def:0,spd:0};persist();render();break;
 case 'badge':if(!badgeRank(a,id))throw Error('未解放です');a.badge=a.badge===id?null:id;persist();render();break;
 case 'claim':claim(a,id);persist();render();toast('60Pを受け取りました');break;
 case 'summon':if($('#modal').open&&summonSession)return;lastSummon=summon(a,Number(id));persist();render();tone();summonSession={results:lastSummon,revealed:0};summonCinema();break;
 case 'summonReveal':case 'summonAll':if(!summonSession||!$('#modal').open)return;summonSession.revealed=action==='summonAll'?summonSession.results.length:Math.min(summonSession.results.length,summonSession.revealed+1);summonPresentation();break;
 case 'fight':{if(id==='selected'){const f=Number($('#floor').value);if(!Number.isInteger(f))throw Error('階層は整数で入力してください');difficulty=$('#difficulty').value;beginFight('normal',{floor:f});}else beginFight(id);break;}
 case 'combat':if(['divine','fallen'].includes(id)){alignmentShift(id);}else if(['genesis','ending'].includes(id)){const reason=available(battle,id);if(reason)throw Error(reason);const routes=id==='genesis'?[['A','神威','攻防速3倍・2ターン'],['B','静寂','敵の通常行動を1回停止'],['C','再臨','すべてのCTをリセット']]:[['A','崩壊','防御無効化3ターン'],['B','断絶','敵強化解除・10ターン禁止'],['C','消滅','重圧解除・5ターン無効']];modal(id==='genesis'?'創世 — ルート選択':'終焉 — ルート選択',`<div class="stack route-choices">${routes.map(([r,title,desc])=>button(title,'route',id+':'+r,'ghost')).join('')}</div>`);}else if(['feather','ultimate','meteor','annihilate'].includes(id)){if(available(battle,id))throw Error(available(battle,id));const isFeather=id==='feather',isStella=id==='meteor';cinema('cut',isFeather?'羽弾':isStella?'天象支配':id==='ultimate'?'超堕天撃':'終極殲滅',isFeather?'黒翼の弾幕、解き放つ。':isStella?'星々よ、我が意志に従え。':'その一撃が、境界を砕く。',()=>doCombat(id),isFeather?1000:isStella?1200:750,isFeather?SCENES.feather:isStella?SCENES.meteor:null);}else doCombat(id);break;
 case 'route':{const [skill,route]=id.split(':');close();cinema('cut',skill==='genesis'?'創世':'終焉','ULTIMATE AUTHORITY',()=>doCombat(skill,route),800,skill==='ending'?MEDIA.fallenSkills.ending:SCENES.genesis);break;}
 case 'askRetreat':confirmDialog('撤退しますか','この戦闘は敗北になります。神域連戦の場合、今回の進行と仮素材を失います。','retreat','');break;
 case 'retreat':battle.result='lose';battle.reward=battle.campaign?settleCampaign(campaign,battle):settle(a,battle);if(!battle.campaign&&(!battle.test||sandbox))persist();close();render();break;
 case 'finish':if(battle?.campaign){battle=null;page='campaign';render();window.scrollTo(0,0);break;}battle=null;page='home';render();window.scrollTo(0,0);break;
 case 'retry':{if(battle?.campaign){battle=null;page='campaign';render();window.scrollTo(0,0);break;}const old=battle;const next=old.result==='win'&&old.mode==='normal'&&old.floor<100?old.floor+1:old.floor;const test=old.test;battle=null;if(old.trial){battle=retryThreePhase(old);page='battle';render();window.scrollTo(0,0);}else if(old.experiment){battle=startBattle(old.build,{mode:old.mode,floor:next,difficulty:old.difficulty,test:true});battle.base={...old.base};battle.hp=battle.base.hp;battle.experiment={...old.experiment};page='battle';render();window.scrollTo(0,0);}else beginFight(old.mode,{floor:next,test});break;}
 case 'warp':if(!a.flags.lv100||a.flags.warp)throw Error('境界はまだ開かれていません');cinema('warp','境界を越えて','STELLA AWAKENED',()=>{warp(a);persist();page='home';render();toast('ステラ解放。EXカイザーへの道が開かれた。');},3500);break;
 case 'awaken':{const lv=awaken(a);persist();render();if(lv===5)playMovie();else cinema('warp',AWAKENINGS[lv],'失われた神性を取り戻した。',null,1600);break;}
 case 'movie':playMovie();break;
 case 'campaignOpen':if(battle&&!battle.result)throw Error('先に現在の戦闘を終了してください');campaign ||= createCampaign();page='campaign';render();window.scrollTo(0,0);break;
 case 'campaignLobby':if(battle&&!battle.result)throw Error('先に現在の戦闘を終了してください');battle=null;page='campaign';render();window.scrollTo(0,0);break;
 case 'campaignFight':if(battle&&!battle.result)throw Error('先に現在の戦闘を終了してください');battle=startCampaignBattle(campaign);page='battle';render();window.scrollTo(0,0);break;
 case 'campaignTrain':campaignTrain(campaign,id);render();break;
 case 'campaignPower':campaignEquip(campaign,id,'power');render();break;
