 case 'labstart':{const mode=$('#labmode').value,atk=Number($('#labatk').value),hp=Number($('#labhp').value);if(!Number.isFinite(atk)||!Number.isFinite(hp)||atk<.1||hp<.1||atk>20||hp>20)throw Error('倍率は0.1〜20で入力してください');if(battle&&!battle.result)throw Error('先に現在の戦闘を終了してください');if(mode==='three-phase')battle=startThreePhase(s,{atk,hp});else{battle=startBattle(developerState(s),{mode,floor:100,test:true});battle.base.atk*=atk;battle.base.hp*=hp;battle.hp=battle.base.hp;battle.experiment={atk,hp};}page='battle';render();break;}
 case 'enabledev':if(battle&&!battle.result)throw Error('先に戦闘を終了してください');sandbox=developerState(s);battle=null;persist();render();toast('独立試験用データを開放しました');break;
