/* Battle feedback uses actual post-turn damage values, including misses and counterattacks. */
.battle-stage .fighter{position:relative;min-width:0}
.battle-stage .combat-number{position:absolute;z-index:8;top:34%;left:50%;transform:translateX(-50%);white-space:nowrap;pointer-events:none;font:900 clamp(21px,3.4vw,40px)/1.1 var(--serif);font-variant-numeric:tabular-nums;letter-spacing:.015em;text-shadow:0 3px 4px #090615,0 0 17px #090615;animation:combat-number-rise .9s cubic-bezier(.16,.7,.3,1) both}
.battle-stage .damage-dealt{color:#fff0bf;filter:drop-shadow(0 0 6px #d09b49)}
.battle-stage .damage-taken{color:#ffbdc5;filter:drop-shadow(0 0 7px #c03455)}
.battle-stage .damage-missed{color:#bfc9e2;font-size:clamp(17px,3vw,27px)}
.battle-stage .impact-foe .portrait-frame{animation:foe-hit-recoil .38s ease-out both}
.battle-stage .impact-player .portrait-frame{animation:player-hit-recoil .38s ease-out both}
.battle-stage .impact-foe .portrait-frame:after,.battle-stage .impact-player .portrait-frame:after{content:'';position:absolute;inset:0;pointer-events:none;animation:impact-glint .38s ease-out both;background:radial-gradient(circle at 50% 47%,#fff9e34d,transparent 75%)}
.battle-stage .impact-player .portrait-frame:after{background:radial-gradient(circle at 50% 47%,#ff51713f,transparent 75%)}

@keyframes combat-number-rise{0%{opacity:0;transform:translate(-50%,12px) scale(.82)}20%{opacity:1;transform:translate(-50%,-8px) scale(1.14)}65%{opacity:1}100%{opacity:0;transform:translate(-50%,-45px) scale(1)}}
@keyframes foe-hit-recoil{0%,100%{transform:translate(0,0)}19%{transform:translate(8px,-3px);filter:brightness(1.55)}38%{transform:translate(-6px,2px)}61%{transform:translate(3px,-1px)}}
@keyframes player-hit-recoil{0%,100%{transform:translate(0,0)}19%{transform:translate(-8px,3px);filter:brightness(1.22)}38%{transform:translate(5px,-2px)}61%{transform:translate(-2px,1px)}}
@keyframes impact-glint{0%{opacity:0}20%{opacity:1}100%{opacity:0}}
@media(max-width:700px){.battle-stage .combat-number{top:37%;font-size:clamp(18px,5.2vw,30px)}}
@media(prefers-reduced-motion:reduce){.battle-stage .combat-number{animation:none;opacity:1}.battle-stage .impact-foe .portrait-frame,.battle-stage .impact-player .portrait-frame,.battle-stage .impact-foe .portrait-frame:after,.battle-stage .impact-player .portrait-frame:after{animation:none}}

